export interface LeadCapture {
  leadCaptureId: number;
  companyId: number;
  fullName: string;
  email: string;
  companyName: string | null;
  phone: string | null;
  jobTitle: string | null;
  message: string | null;
  leadSource: string;
  interestArea: string | null;
  status: string;
  assignedTo: number | null;
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at: string | null;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

export async function getAllLeadCaptures(companyId: number): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ companyId: companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

export async function createLeadCapture(payload: Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at">): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ action: 1, ...payload }] }),
  });
  // ADR-002: Check for embedded error field in the response body
  const result = await res.json();
  if (!res.ok || (result.leadCaptures && result.leadCaptures[0] && result.leadCaptures[0].error)) {
    const errorMessage = result.leadCaptures && result.leadCaptures[0] && result.leadCaptures[0].msg ? result.leadCaptures[0].msg : (await res.text() || 'Error desconocido');
    throw new Error(errorMessage);
  }
  return result;
}

export async function updateLeadCapture(id: number, payload: Partial<LeadCapture>): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ action: 2, leadCaptureId: id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

export async function deleteLeadCapture(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ leadCaptures: [{ action: 3, leadCaptureId: id, companyId: companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
