          header="Confirmar Eliminación"
          message="¿Estás seguro de que quieres eliminar este lead?"
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: handleDeleteLead, cssClass: 'danger' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
